{"command": "cd /workspace; python3 - <<'EOF'
import pty, os, sys
def run_tty(cmd, input_data):
    pid, fd = pty.fork()
    if pid == 0:
        os.execvp('sh', ['sh', '-c', cmd])
    os.write(fd, input_data.encode())
    out = b''
    try:
        while True:
            d = os.read(fd, 4096)
            if not d: break
            out += d
    except OSError:
        pass
    os.waitpid(pid, 0)
    return out.decode(errors='replace')
print(repr(run_tty('printf \'"#"; some of <word>;\' | ./executable', '')))
EOF"}

